199:             return;
200:         }
201:         MONITORINFOEXW activeMonitor = getMonitorForWindow(oldForegroundWindow);
202:         // We need to show the window first, otherwise we won't be able to bring it to front.
203:         if (!::IsWindowVisible(hwnd)) {
204:             ::ShowWindow(hwnd, SW_SHOW);
205:         }
206:         if (isMinimized(hwnd)) {
207:             // Restore the window if it is minimized.
208:             ::ShowWindow(hwnd, SW_RESTORE);
209:             // Once we've been restored, throw us on the active monitor.
210:             moveWindowToMonitor(hwnd, activeMonitor);
211:             // When the window is restored, it will always become the foreground window.
212:             // So return early here, we don't need the following code to bring it to front.
213:             return;
