243:     // Returns false if the menu is canceled
244:     static bool showSystemMenu_sys(HWND hWnd, const POINT &pos, const bool selectFirstEntry,
245:                                    const bool fixedSize) {
246:         Q_ASSERT(hWnd);
247:         HMENU hMenu = ::GetSystemMenu(hWnd, FALSE);
248:         if (!hMenu) {
249:             // The corresponding window doesn't have a system menu, most likely due to the
250:             // lack of the "WS_SYSMENU" window style. This situation should not be treated
251:             // as an error so just ignore it and return early.
252:             return true;
253:         }
254: 
255:         const auto windowStyles = ::GetWindowLongPtrW(hWnd, GWL_STYLE);
256:         const bool allowMaximize = windowStyles & WS_MAXIMIZEBOX;
257:         const bool allowMinimize = windowStyles & WS_MINIMIZEBOX;
258: 
259:         const bool maxOrFull = isMaximized(hWnd) || isFullScreen(hWnd);
260:         ::EnableMenuItem(hMenu, SC_CLOSE, (MF_BYCOMMAND | MFS_ENABLED));
261:         ::EnableMenuItem(
262:             hMenu, SC_MAXIMIZE,
263:             (MF_BYCOMMAND |
264:              ((maxOrFull || fixedSize || !allowMaximize) ? MFS_DISABLED : MFS_ENABLED)));
265:         ::EnableMenuItem(
266:             hMenu, SC_RESTORE,
267:             (MF_BYCOMMAND |
268:              ((maxOrFull && !fixedSize && allowMaximize) ? MFS_ENABLED : MFS_DISABLED)));
269:         // The first menu item should be selected by default if the menu is brought
270:         // up by keyboard. I don't know how to pre-select a menu item but it seems
271:         // highlight can do the job. However, there's an annoying issue if we do
272:         // this manually: the highlighted menu item is really only highlighted,
273:         // not selected, so even if the mouse cursor hovers on other menu items
274:         // or the user navigates to other menu items through keyboard, the original
275:         // highlight bar will not move accordingly, the OS will generate another
276:         // highlight bar to indicate the current selected menu item, which will make
277:         // the menu look kind of weird. Currently I don't know how to fix this issue.
278:         ::HiliteMenuItem(hWnd, hMenu, SC_RESTORE,
279:                          (MF_BYCOMMAND | (selectFirstEntry ? MFS_HILITE : MFS_UNHILITE)));
280:         ::EnableMenuItem(hMenu, SC_MINIMIZE,
281:                          (MF_BYCOMMAND | (allowMinimize ? MFS_ENABLED : MFS_DISABLED)));
282:         ::EnableMenuItem(hMenu, SC_SIZE,
283:                          (MF_BYCOMMAND | ((maxOrFull || fixedSize) ? MFS_DISABLED : MFS_ENABLED)));
284:         ::EnableMenuItem(hMenu, SC_MOVE, (MF_BYCOMMAND | (maxOrFull ? MFS_DISABLED : MFS_ENABLED)));
285: 
286:         // The default menu item will appear in bold font. There can only be one default
287:         // menu item per menu at most. Set the item ID to "UINT_MAX" (or simply "-1")
288:         // can clear the default item for the given menu.
289:         UINT defaultItemId = UINT_MAX;
290:         if (isWin11OrGreater()) {
291:             if (maxOrFull) {
292:                 defaultItemId = SC_RESTORE;
293:             } else {
294:                 defaultItemId = SC_MAXIMIZE;
295:             }
296:         }
297:         if (defaultItemId == UINT_MAX) {
298:             defaultItemId = SC_CLOSE;
299:         }
300:         ::SetMenuDefaultItem(hMenu, defaultItemId, FALSE);
301: 
302:         // Popup the system menu at the required position.
303:         const auto result = ::TrackPopupMenu(
304:             hMenu,
305:             (TPM_RETURNCMD | (QGuiApplication::isRightToLeft() ? TPM_RIGHTALIGN : TPM_LEFTALIGN) |
306:              TPM_RIGHTBUTTON),
307:             pos.x, pos.y, 0, hWnd, nullptr);
308: 
309:         // Unhighlight the first menu item after the popup menu is closed, otherwise it will keep
310:         // highlighting until we unhighlight it manually.
311:         ::HiliteMenuItem(hWnd, hMenu, SC_RESTORE, (MF_BYCOMMAND | MFS_UNHILITE));
312: 
313:         if (!result) {
314:             // The user canceled the menu, no need to continue.
315:             return false;
316:         }
317: 
318:         // Send the command that the user chooses to the corresponding window.
319:         ::PostMessageW(hWnd, WM_SYSCOMMAND, result, 0);
320:         return true;
321:     }
