352:     static bool isValidWindow(HWND hWnd, bool checkVisible, bool checkTopLevel) {
353:         Q_ASSERT(hWnd);
354:         if (!::IsWindow(hWnd)) {
355:             return false;
356:         }
357:         const LONG_PTR styles = ::GetWindowLongPtrW(hWnd, GWL_STYLE);
358:         if (styles & WS_DISABLED) {
359:             return false;
360:         }
361:         const LONG_PTR exStyles = ::GetWindowLongPtrW(hWnd, GWL_EXSTYLE);
362:         if (exStyles & WS_EX_TOOLWINDOW) {
363:             return false;
364:         }
365:         RECT rect{};
366:         if (!::GetWindowRect(hWnd, &rect)) {
367:             return false;
368:         }
369:         if ((rect.left >= rect.right) || (rect.top >= rect.bottom)) {
370:             return false;
371:         }
372:         if (checkVisible) {
373:             if (!::IsWindowVisible(hWnd)) {
374:                 return false;
375:             }
376:         }
377:         if (checkTopLevel) {
378:             if (::GetAncestor(hWnd, GA_ROOT) != hWnd) {
379:                 return false;
380:             }
381:         }
382:         return true;
383:     }
