385:     static inline constexpr bool isNonClientMessage(const UINT message) {
386:         if (((message >= WM_NCCREATE) && (message <= WM_NCACTIVATE)) ||
387:             ((message >= WM_NCMOUSEMOVE) && (message <= WM_NCMBUTTONDBLCLK)) ||
388:             ((message >= WM_NCXBUTTONDOWN) && (message <= WM_NCXBUTTONDBLCLK))
389: #if (WINVER >= _WIN32_WINNT_WIN8)
390:             || ((message >= WM_NCPOINTERUPDATE) && (message <= WM_NCPOINTERUP))
391: #endif
392:             || ((message == WM_NCMOUSEHOVER) || (message == WM_NCMOUSELEAVE))) {
393:             return true;
394:         } else {
395:             return false;
396:         }
