419:     static inline constexpr bool isInputMessage(UINT m) {
420:         switch (m) {
421:             case WM_IME_STARTCOMPOSITION:
422:             case WM_IME_ENDCOMPOSITION:
423:             case WM_IME_COMPOSITION:
424:             case WM_INPUT:
425:             case WM_TOUCH:
426:             case WM_MOUSEHOVER:
427:             case WM_MOUSELEAVE:
428:             case WM_NCMOUSEHOVER:
429:             case WM_NCMOUSELEAVE:
430:             case WM_SIZING:
431:             case WM_MOVING:
432:             case WM_SYSCOMMAND:
433:             case WM_COMMAND:
434:             case WM_DWMNCRENDERINGCHANGED:
435:             case WM_PAINT:
436:                 return true;
437:             default:
438:                 break;
439:         }
440:         return (m >= WM_MOUSEFIRST && m <= WM_MOUSELAST) ||
441:                (m >= WM_NCMOUSEMOVE && m <= WM_NCXBUTTONDBLCLK) ||
442:                (m >= WM_KEYFIRST && m <= WM_KEYLAST);
443:     }
