449:     // Send to QAbstractEventDispatcher
450:     static bool filterNativeEvent(MSG *msg, LRESULT *result) {
451:         Q_ASSERT(msg);
452:         Q_ASSERT(result);
453:         auto dispatcher = QAbstractEventDispatcher::instance();
454:         QT_NATIVE_EVENT_RESULT_TYPE filterResult = *result;
455:         if (dispatcher && dispatcher->filterNativeEvent(nativeEventType(), msg, &filterResult)) {
456:             *result = LRESULT(filterResult);
457:             return true;
458:         }
459:         return false;
460:     }
