462:     // Send to QWindowSystemInterface
463:     static bool filterNativeEvent(QWindow *window, MSG *msg, LRESULT *result) {
464:         Q_ASSERT(window);
465:         Q_ASSERT(msg);
466:         Q_ASSERT(result);
467:         QT_NATIVE_EVENT_RESULT_TYPE filterResult = *result;
468:         if (QWindowSystemInterface::handleNativeEvent(window, nativeEventType(), msg,
469:                                                       &filterResult)) {
470:             *result = LRESULT(filterResult);
471:             return true;
472:         }
473:         return false;
474:     }
