476:     static inline bool forwardFilteredEvent(QWindow *window, HWND hWnd, UINT message, WPARAM wParam,
477:                                             LPARAM lParam, LRESULT *result) {
478:         Q_ASSERT(window);
479:         Q_ASSERT(hWnd);
480:         Q_ASSERT(result);
481: 
482:         MSG msg = createMessageBlock(hWnd, message, wParam, lParam);
483: 
484:         // https://github.com/qt/qtbase/blob/e26a87f1ecc40bc8c6aa5b889fce67410a57a702/src/plugins/platforms/windows/qwindowscontext.cpp#L1025
485:         // Do exact the same as what Qt Windows plugin does.
486: 
487:         // Run the native event filters. QTBUG-67095: Exclude input messages which are sent
488:         // by QEventDispatcherWin32::processEvents()
489:         if (!isInputMessage(msg.message) && filterNativeEvent(&msg, result))
490:             return true;
491: 
492:         auto platformWindow = window->handle();
493:         if (platformWindow && filterNativeEvent(platformWindow->window(), &msg, result))
494:             return true;
495: 
496:         return false;
497:     }
