499:     // https://github.com/qt/qtbase/blob/e26a87f1ecc40bc8c6aa5b889fce67410a57a702/src/plugins/platforms/windows/qwindowscontext.cpp#L1556
500:     // In QWindowsContext::windowsProc(), the messages will be passed to all global native event
501:     // filters, but because we have already filtered the messages in the hook WndProc function for
502:     // convenience, Qt does not know we may have already processed the messages and thus will call
503:     // DefWindowProc(). Consequently, we have to add a global native filter that forwards the result
504:     // of the hook function, telling Qt whether we have filtered the events before. Since Qt only
505:     // handles Windows window messages in the main thread, it is safe to do so.
506:     class WindowsNativeEventFilter : public AppNativeEventFilter {
507:     public:
508:         bool nativeEventFilter(const QByteArray &eventType, void *message,
509:                                QT_NATIVE_EVENT_RESULT_TYPE *result) override {
510:             Q_UNUSED(eventType)
511: 
512:             // It has been observed that the pointer that Qt gives us is sometimes null on some
513:             // machines. We need to guard against it in such scenarios.
514:             if (!result || !message) {
515:                 return false;
516:             }
517: 
518:             auto msg = static_cast<const MSG *>(message);
519:             switch (msg->message) {
520:                 case WM_NCCALCSIZE: {
521:                     // https://github.com/qt/qtbase/blob/e26a87f1ecc40bc8c6aa5b889fce67410a57a702/src/plugins/platforms/windows/qwindowscontext.cpp#L1546
522:                     // Qt needs to refer to the WM_NCCALCSIZE message data that hasn't been
523:                     // processed, so we have to process it after Qt acquires the initial data.
524:                     if (lastMessageContext) {
525:                         LRESULT res;
526:                         if (lastMessageContext->nonClientCalcSizeHandler(
527:                                 msg->hwnd, msg->message, msg->wParam, msg->lParam, &res)) {
528:                             *result = decltype(*result)(res);
529:                             return true;
530:                         }
531:                     }
532:                     break;
533:                 }
534: 
535:                     // case WM_NCHITTEST: {
536:                     //     // The child window must return HTTRANSPARENT when processing WM_NCHITTEST for
537:                     //     // the parent window to receive WM_NCHITTEST.
538:                     //     if (!lastMessageContext) {
539:                     //         auto rootHWnd = ::GetAncestor(msg->hwnd, GA_ROOT);
540:                     //         if (rootHWnd != msg->hwnd) {
541:                     //             if (auto ctx = g_wndProcHash->value(rootHWnd)) {
542:                     //                 *result = HTTRANSPARENT;
543:                     //                 return true;
544:                     //             }
545:                     //         }
546:                     //     }
547:                     //     break;
548:                     // }
549:             }
550:             return false;
551:         }
552: 
553:         static inline WindowsNativeEventFilter *instance = nullptr;
554:         static inline Win32WindowContext *lastMessageContext = nullptr;
555: 
556:         static inline void install() {
557:             if (instance) {
558:                 return;
559:             }
560:             instance = new WindowsNativeEventFilter();
561:         }
562: 
563:         static inline void uninstall() {
564:             if (!instance) {
565:                 return;
566:             }
567:             delete std::exchange(instance, nullptr);
568:         }
569:     };
570: 
571:     // https://github.com/qt/qtbase/blob/e26a87f1ecc40bc8c6aa5b889fce67410a57a702/src/plugins/platforms/windows/qwindowscontext.cpp#L1025
572:     // We can see from the source code that Qt will filter out some messages first and then send the
573:     // unfiltered messages to the event dispatcher. To activate the Snap Layout feature on Windows
574:     // 11, we must process some non-client area messages ourselves, but unfortunately these messages
575:     // have been filtered out already in that line, and thus we'll never have the chance to process
576:     // them ourselves. This is Qt's low level platform specific code, so we don't have any official
577:     // ways to change this behavior. But luckily we can replace the window procedure function of
578:     // Qt's windows, and in this hooked window procedure function, we finally have the chance to
579:     // process window messages before Qt touches them. So we reconstruct the MSG structure and send
580:     // it to our own custom native event filter to do all the magic works. But since the system menu
581:     // feature doesn't necessarily belong to the native implementation, we seperate the handling
582:     // code and always process the system menu part in this function for both implementations.
583:     //
584:     // Original event flow:
585:     //      [Entry]             Windows Message Queue
586:     //                          |
587:     //      [Qt Window Proc]    qwindowscontext.cpp#L1547: qWindowsWndProc()
588:     //                              ```
589:     //                              const bool handled = QWindowsContext::instance()->windowsProc
590:     //                                  (hwnd, message, et, wParam, lParam, &result,
591:     //                                  &platformWindow);
592:     //                              ```
593:     //                          |
594:     //      [Non-Input Filter]  qwindowscontext.cpp#L1025: QWindowsContext::windowsProc()
595:     //                              ```
596:     //                              if (!isInputMessage(msg.message) &&
597:     //                                  filterNativeEvent(&msg, result))
598:     //                                  return true;
599:     //                              ```
600:     //                          |
601:     //      [User Filter]       qwindowscontext.cpp#L1588: QWindowsContext::windowsProc()
602:     //                              ```
603:     //                              QAbstractEventDispatcher *dispatcher =
604:     //                              QAbstractEventDispatcher::instance();
605:     //                              qintptr filterResult = 0;
606:     //                              if (dispatcher &&
607:     //                              dispatcher->filterNativeEvent(nativeEventType(), msg,
608:     //                              &filterResult)) {
609:     //                                  *result = LRESULT(filterResult);
610:     //                                  return true;
611:     //                              }
612:     //                              ```
613:     //                          |
614:     //      [Extra work]        The rest of QWindowsContext::windowsProc() and qWindowsWndProc()
615:     //
616:     // Notice: Only non-input messages will be processed by the user-defined global native event
617:     // filter!!! These events are then passed to the widget class's own overridden
618:     // QWidget::nativeEvent() as a local filter, where all native events can be handled, but we must
619:     // create a new class derived from QWidget which we don't intend to. Therefore, we don't expect
620:     // to process events from the global native event filter, but instead hook Qt's window
621:     // procedure.
622: 
623:     extern "C" LRESULT QT_WIN_CALLBACK QWKHookedWndProc(HWND hWnd, UINT message, WPARAM wParam,
624:                                                         LPARAM lParam) {
625:         Q_ASSERT(hWnd);
626:         if (!hWnd) {
627:             return FALSE;
628:         }
629: 
630:         // QWindow may have been destroyed before WinIdChange event comes
631:         auto ctx = g_wndProcHash->value(hWnd);
632:         if (!ctx || !ctx->window()) {
633:             return ::CallWindowProcW(g_qtWindowProc, hWnd, message, wParam, lParam);
634:         }
635: 
636:         WindowsNativeEventFilter::lastMessageContext = ctx;
637:         const auto &contextCleaner = qScopeGuard([]() {
638:             WindowsNativeEventFilter::lastMessageContext = nullptr; //
639:         });
640: 
641:         // Since Qt does the necessary processing of the WM_NCCALCSIZE message, we need to
642:         // forward it right away and process it in our native event filter.
643:         if (message == WM_NCCALCSIZE) {
644:             return ::CallWindowProcW(g_qtWindowProc, hWnd, message, wParam, lParam);
645:         }
646: 
647:         // Try hooked procedure and save result
648:         LRESULT result;
649:         if (ctx->windowProc(hWnd, message, wParam, lParam, &result)) {
650:             // https://github.com/stdware/qwindowkit/issues/45
651:             // Forward the event to user-defined native event filters, there may be some messages
652:             // that need to be processed by the user.
653:             std::ignore =
654:                 forwardFilteredEvent(ctx->window(), hWnd, message, wParam, lParam, &result);
655:             return result;
656:         }
657: 
658:         // Continue dispatching.
659:         return ::CallWindowProcW(g_qtWindowProc, hWnd, message, wParam, lParam);
660:     }
