662:     static inline void addManagedWindow(QWindow *window, HWND hWnd, Win32WindowContext *ctx) {
663:         Q_ASSERT(window);
664:         Q_ASSERT(hWnd);
665:         Q_ASSERT(ctx);
666: 
667:         if (isSystemBorderEnabled()) {
668:             // Inform Qt we want and have set custom margins
669:             setInternalWindowFrameMargins(window, QMargins(0, -int(getTitleBarHeight(hWnd)), 0, 0));
670:         }
671: 
672:         // Store original window proc
673:         if (!g_qtWindowProc) {
674:             g_qtWindowProc = reinterpret_cast<WNDPROC>(::GetWindowLongPtrW(hWnd, GWLP_WNDPROC));
675:         }
676: 
677:         // Hook window proc
678:         ::SetWindowLongPtrW(hWnd, GWLP_WNDPROC, reinterpret_cast<LONG_PTR>(QWKHookedWndProc));
679: 
680:         // Install global native event filter
681:         WindowsNativeEventFilter::install();
682: 
683:         // Save window handle mapping
684:         g_wndProcHash->insert(hWnd, ctx);
685: 
686:         // Force a WM_NCCALCSIZE message manually to avoid the title bar become visible
687:         // while Qt is re-creating the window (such as setWindowFlag(s) calls). It has
688:         // been observed by our users.
689:         triggerFrameChange(hWnd);
690:     }
691: 
692:     static inline void removeManagedWindow(HWND hWnd) {
693:         Q_ASSERT(hWnd);
694: 
695:         // Remove window handle mapping
696:         if (!g_wndProcHash->remove(hWnd))
697:             return;
698: 
699:         // Remove event filter if the all windows has been destroyed
700:         if (g_wndProcHash->empty()) {
701:             WindowsNativeEventFilter::uninstall();
702:         }
703:     }
