717:     void Win32WindowContext::virtual_hook(int id, void *data) {
718:         switch (id) {
719:             case RaiseWindowHook: {
720:                 if (!m_windowId)
721:                     return;
722:                 m_delegate->setWindowVisible(m_host, true);
723:                 const auto hwnd = reinterpret_cast<HWND>(m_windowId);
724:                 bringWindowToFront(hwnd);
725:                 return;
726:             }
727: 
728:             case ShowSystemMenuHook: {
729:                 if (!m_windowId)
730:                     return;
731:                 const auto &pos = *static_cast<const QPoint *>(data);
732:                 auto hWnd = reinterpret_cast<HWND>(m_windowId);
733: #if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
734:                 const QPoint nativeGlobalPos =
735:                     QHighDpi::toNativeGlobalPosition(pos, m_windowHandle.data());
736: #else
737:                 const QPoint nativeGlobalPos = QHighDpi::toNativePixels(pos, m_windowHandle.data());
738: #endif
739:                 std::ignore = showSystemMenu_sys(hWnd, qpoint2point(nativeGlobalPos), false,
740:                                                  isHostSizeFixed());
741:                 return;
742:             }
743: 
744:             case DefaultColorsHook: {
745:                 auto &map = *static_cast<QMap<QString, QColor> *>(data);
746:                 map.clear();
747:                 map.insert(QStringLiteral("activeLight"), kWindowsColorSet.activeLight);
748:                 map.insert(QStringLiteral("activeDark"), kWindowsColorSet.activeDark);
749:                 map.insert(QStringLiteral("inactiveLight"), kWindowsColorSet.inactiveLight);
750:                 map.insert(QStringLiteral("inactiveDark"), kWindowsColorSet.inactiveDark);
751:                 return;
752:             }
753: 
754: #if QWINDOWKIT_CONFIG(ENABLE_WINDOWS_SYSTEM_BORDERS)
755:             // ### FIXME: May be deprecated
756:             case DrawWindows10BorderHook_Emulated: {
757:                 if (!m_windowId)
758:                     return;
759: 
760:                 auto args = static_cast<void **>(data);
761:                 auto &painter = *static_cast<QPainter *>(args[0]);
762:                 const auto &rect = *static_cast<const QRect *>(args[1]);
763:                 const auto &region = *static_cast<const QRegion *>(args[2]);
764:                 const auto hwnd = reinterpret_cast<HWND>(m_windowId);
765: 
766:                 QPen pen;
767: #  if QT_VERSION_MAJOR < 6
768:                 pen.setWidth(1);
769: #  else
770:                 pen.setWidthF(1 / m_windowHandle->devicePixelRatio()); // why 0.25?
771: #  endif
772: 
773:                 const bool dark = isDarkThemeActive() && isDarkWindowFrameEnabled(hwnd);
774:                 if (m_delegate->isWindowActive(m_host)) {
775:                     if (isWindowFrameBorderColorized()) {
776:                         pen.setColor(getAccentColor());
777:                     } else {
778:                         static QColor frameBorderActiveColorLight(kWindowsColorSet.activeLight);
779:                         static QColor frameBorderActiveColorDark(kWindowsColorSet.activeDark);
780:                         pen.setColor(dark ? frameBorderActiveColorDark
781:                                           : frameBorderActiveColorLight);
782:                     }
783:                 } else {
784:                     static QColor frameBorderInactiveColorLight(kWindowsColorSet.inactiveLight);
785:                     static QColor frameBorderInactiveColorDark(kWindowsColorSet.inactiveDark);
786:                     pen.setColor(dark ? frameBorderInactiveColorDark
787:                                       : frameBorderInactiveColorLight);
788:                 }
789:                 painter.save();
790: 
791:                 // We need antialiasing to give us better result.
792:                 painter.setRenderHint(QPainter::Antialiasing);
793: 
794:                 painter.setPen(pen);
795:                 painter.drawLine(QLine{
796:                     QPoint{0,                       0},
797:                     QPoint{m_windowHandle->width(), 0}
798:                 });
799:                 painter.restore();
800:                 return;
801:             }
