874:     void Win32WindowContext::winIdChanged(WId winId, WId oldWinId) {
875:         // Reset the context data
876:         mouseLeaveBlocked = false;
877:         lastHitTestResult = WindowPart::Outside;
878:         lastHitTestResultRaw = HTNOWHERE;
879: 
880:         // If the original window id is valid, remove all resources related
881:         if (oldWinId) {
882:             removeManagedWindow(reinterpret_cast<HWND>(oldWinId));
883:         }
884:         if (!winId) {
885:             return;
886:         }
887: 
888:         // Install window hook
889:         auto hWnd = reinterpret_cast<HWND>(winId);
890:         if (!isSystemBorderEnabled()) {
891:             static auto margins = QVariant::fromValue(QMargins(1, 1, 1, 1));
892: 
893:             // If we remove the system border, the window will lose its shadow. If dwm is enabled,
894:             // then we need to set at least 1px margins, otherwise the following operation will
895:             // fail with no effect.
896:             setWindowAttribute(QStringLiteral("extra-margins"), margins);
897:         }
898: 
899:         // We should disable WS_SYSMENU, otherwise the system button icons will be visible if mica
900:         // is enabled and the title bar is transparent.
901:         {
902:             auto style = ::GetWindowLongPtrW(hWnd, GWL_STYLE);
903:             if (isSystemBorderEnabled()) {
904:                 ::SetWindowLongPtrW(hWnd, GWL_STYLE, style & (~WS_SYSMENU));
905:             } else {
906:                 ::SetWindowLongPtrW(hWnd, GWL_STYLE,
907:                                     (style | WS_THICKFRAME | WS_CAPTION) & (~WS_SYSMENU));
908:             }
909:         }
910: 
911:         // Add managed window
912:         addManagedWindow(m_windowHandle, hWnd, this);
913:     }
