919: 
920:         *result = FALSE;
921: 
922:         // We should skip these messages otherwise we will get crashes.
923:         // NOTE: WM_QUIT won't be posted to the WindowProc function.
924:         switch (message) {
925:             case WM_DESTROY:
926:             case WM_CLOSE:
927:             case WM_NCDESTROY:
928:             // Undocumented messages:
929:             case WM_UAHDESTROYWINDOW:
930:             case WM_UNREGISTER_WINDOW_SERVICES:
931:                 return false;
932:             default:
933:                 break;
934:         }
935: 
936:         if (!isValidWindow(hWnd, false, true)) {
937:             return false;
938:         }
939: 
940:         // Test snap layout
941:         if (snapLayoutHandler(hWnd, message, wParam, lParam, result)) {
942:             return true;
943:         }
944: 
945:         // Main implementation
946:         if (customWindowHandler(hWnd, message, wParam, lParam, result)) {
947:             return true;
948:         }
949: 
950:         // Whether to show system menu
951:         if (!noSystemMenu && systemMenuHandler(hWnd, message, wParam, lParam, result)) {
952:             return true;
953:         }
