955:         // Forward to native event filter subscribers
956:         if (!m_nativeEventFilters.isEmpty()) {
957:             MSG msg = createMessageBlock(hWnd, message, wParam, lParam);
958:             QT_NATIVE_EVENT_RESULT_TYPE res = 0;
959:             if (nativeDispatch(nativeEventType(), &msg, &res)) {
960:                 *result = LRESULT(res);
961:                 return true;
962:             }
963:         }
964:         return false; // Not handled
965:     }
