255:         void updateSystemButtonRect() {
256:             if (!screenRectCallback || !systemButtonVisible) {
257:                 return;
258:             }
259:             const auto &buttons = systemButtons();
260:             const auto &leftButton = buttons[0];
261:             const auto &midButton = buttons[1];
262:             const auto &rightButton = buttons[2];
263: 
264:             auto titlebar = rightButton.superview;
265:             int titlebarHeight = titlebar.frame.size.height;
266: 
267:             auto spacing = midButton.frame.origin.x - leftButton.frame.origin.x;
268:             auto width = midButton.frame.size.width;
269:             auto height = midButton.frame.size.height;
270: 
271:             auto viewSize = nsview.frame.size;
272:             QPoint center = screenRectCallback(QSize(viewSize.width, titlebarHeight)).center();
273: 
274:             // The origin of the NSWindow coordinate system is in the lower left corner, we
275:             // do the necessary transformations
276:             center.ry() = titlebarHeight - center.y();
277: 
278:             // Mid button
279:             NSPoint centerOrigin = {
280:                 center.x() - width / 2,
281:                 center.y() - height / 2,
282:             };
283:             [midButton setFrameOrigin:centerOrigin];
284: 
285:             // Left button
286:             NSPoint leftOrigin = {
287:                 centerOrigin.x - spacing,
288:                 centerOrigin.y,
289:             };
290:             [leftButton setFrameOrigin:leftOrigin];
291: 
292:             // Right button
293:             NSPoint rightOrigin = {
294:                 centerOrigin.x + spacing,
295:                 centerOrigin.y,
296:             };
297:             [rightButton setFrameOrigin:rightOrigin];
298:         }
