474: 
475:             if (!glassContainerLayerStateCaptured) {
476:                 originalGlassContainerWantsLayer = container.wantsLayer;
477:                 if (container.layer) {
478:                     originalGlassContainerCornerRadius = container.layer.cornerRadius;
479:                     originalGlassContainerMasksToBounds = container.layer.masksToBounds;
480:                 }
481:                 glassContainerLayerStateCaptured = true;
482:             }
483: 
484:             const auto needsCustomRadius = glassMode != GlassMode::None && glassCornerRadius > 0;
485:             container.wantsLayer = needsCustomRadius || originalGlassContainerWantsLayer;
486: 
487:             auto layer = container.layer;
488:             if (!layer) {
489:                 return;
490:             }
491: 
492:             layer.cornerRadius = needsCustomRadius ? glassCornerRadius
493:                                                    : originalGlassContainerCornerRadius;
494:             layer.masksToBounds = needsCustomRadius ? YES : originalGlassContainerMasksToBounds;
495: 
496:             if (!needsCustomRadius && !originalGlassContainerWantsLayer) {
497:                 container.wantsLayer = NO;
498:             }
499:         }
