868:     CocoaWindowEventFilter::CocoaWindowEventFilter(AbstractWindowContext *context)
869:         : m_context(context), m_cursorShapeChanged(false), m_windowStatus(Idle) {
870:         m_context->installSharedEventFilter(this);
