874: 
875:     bool CocoaWindowEventFilter::sharedEventFilter(QObject *obj, QEvent *event) {
876:         Q_UNUSED(obj)
877: 
878:         auto type = event->type();
879:         if (type < QEvent::MouseButtonPress || type > QEvent::MouseMove) {
880:             return false;
881:         }
882:         auto host = m_context->host();
883:         auto window = m_context->window();
884:         auto delegate = m_context->delegate();
885:         auto me = static_cast<const QMouseEvent *>(event);
886: 
887:         QPoint scenePos = getMouseEventScenePos(me);
888:         QPoint globalPos = getMouseEventGlobalPos(me);
889: 
890:         bool inTitleBar = m_context->isInTitleBarDraggableArea(scenePos);
891:         switch (type) {
892:             case QEvent::MouseButtonPress: {
