424:     inline QColor getAccentColor() {
425: #if QT_VERSION >= QT_VERSION_CHECK(6, 6, 0)
426:         return QGuiApplication::palette().color(QPalette::Accent);
427: #else
428:         WindowsRegistryKey registry(HKEY_CURRENT_USER, LR"(Software\Microsoft\Windows\DWM)");
429:         if (!registry.isValid()) {
430:             return {};
431:         }
432:         auto value = registry.dwordValue(L"AccentColor");
433:         if (!value.second) {
434:             return {};
435:         }
436:         // The retrieved value is in the #AABBGGRR format, we need to
437:         // convert it to the #AARRGGBB format which Qt expects.
438:         QColor color = QColor::fromRgba(value.first);
439:         if (!color.isValid()) {
440:             return {};
441:         }
442:         return QColor::fromRgb(color.blue(), color.green(), color.red(), color.alpha());
443: #endif
444:     }
