446:     inline quint32 getDpiForWindow(HWND hwnd) {
447:         Q_ASSERT(hwnd);
448:         const DynamicApis &apis = DynamicApis::instance();
449:         if (apis.pGetDpiForWindow) { // Win10
450:             return apis.pGetDpiForWindow(hwnd);
451:         } else if (apis.pGetDpiForMonitor) { // Win8.1
452:             HMONITOR monitor = ::MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
453:             UINT dpiX{0};
454:             UINT dpiY{0};
455:             apis.pGetDpiForMonitor(monitor, MDT_EFFECTIVE_DPI, &dpiX, &dpiY);
456:             return dpiX;
457:         } else { // Win2K
458:             HDC hdc = ::GetDC(nullptr);
459:             const int dpiX = ::GetDeviceCaps(hdc, LOGPIXELSX);
460:             // const int dpiY = ::GetDeviceCaps(hdc, LOGPIXELSY);
461:             ::ReleaseDC(nullptr, hdc);
462:             return quint32(dpiX);
463:         }
464:     }
