466:     inline quint32 getSystemMetricsForDpi(int index, quint32 dpi) {
467:         const DynamicApis &apis = DynamicApis::instance();
468:         if (apis.pGetSystemMetricsForDpi) {
469:             return apis.pGetSystemMetricsForDpi(index, dpi);
470:         }
471:         const int result = ::GetSystemMetrics(index);
472:         // GetSystemMetrics() always give you scaled value.
473:         if (dpi != USER_DEFAULT_SCREEN_DPI) {
474:             return result;
475:         }
476:         const qreal dpr = qreal(dpi) / qreal(USER_DEFAULT_SCREEN_DPI);
477:         // ### Not sure how Windows itself rounds non-integer value.
478:         return qFloor(qreal(result) / dpr);
479:     }
