482:         Q_ASSERT(hwnd);
483:         const DynamicApis &apis = DynamicApis::instance();
484:         if (isWin11OrGreater()) {
485:             UINT result = 0;
486:             if (SUCCEEDED(apis.pDwmGetWindowAttribute(hwnd, _DWMWA_VISIBLE_FRAME_BORDER_THICKNESS,
487:                                                       &result, sizeof(result)))) {
488:                 return result;
489:             }
490:         }
491:         if (isWin10OrGreater()) {
492:             const quint32 dpi = getDpiForWindow(hwnd);
493:             // When DPI is 96, it should be 1px.
494:             return getSystemMetricsForDpi(SM_CXBORDER, dpi);
495:         }
496:         // There's no such thing (a visible frame border line) before Win10.
497:         return 0;
