500:     inline quint32 getResizeBorderThickness(HWND hwnd) {
501:         Q_ASSERT(hwnd);
502:         const quint32 dpi = getDpiForWindow(hwnd);
503:         // When DPI is 96, SM_CXSIZEFRAME is 4px, SM_CXPADDEDBORDER is also 4px,
504:         // so the result should be 8px. This result won't be affected by OS version,
505:         // it's 8px in Win7, and so in Win11.
506:         return getSystemMetricsForDpi(SM_CXSIZEFRAME, dpi) +
507:                getSystemMetricsForDpi(SM_CXPADDEDBORDER, dpi);
